// This function will be called once before all tests run
// Use it to set up global state, start services, etc.
async function globalSetup(globalConfig) {
  // Example setup tasks:
  // - Start a database server
  // - Create temporary directories
  // - Set up authentication tokens
  // - Configure environment variables

  // Write the system prompt to a file for testing environment verification
  const fs = require('fs');
  const path = require('path');

  // Create the test output directory if it doesn't exist
  const outputDir = path.join(process.cwd(), 'test-results');
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  // Write the environment snapshot
  const snapshotPath = path.join(outputDir, 'test_env_snapshot.txt');

  // Get system information for the snapshot
  const systemPrompt = `Test Environment Snapshot\n` +
    `========================\n` +
    `Node.js Version: ${process.version}\n` +
    `Platform: ${process.platform}\n` +
    `Architecture: ${process.arch}\n` +
    `Process ID: ${process.pid}\n` +
    `Current Directory: ${process.cwd()}\n` +
    `Execution Time: ${new Date().toISOString()}\n`;

  fs.writeFileSync(snapshotPath, systemPrompt);

  console.log(`Wrote test environment snapshot to ${snapshotPath}`);

  // The return value of this function can be accessed in your test environment
  // via globalThis.globalConfig
  return {};
}

