async function setup() {
  // Write the system prompt to a file for testing environment verification
  const fs = require('fs');
  const path = require('path');

  // Define the system prompt (this would typically be read from an actual source)
  const systemPrompt = `You are an AI assistant running inside OpenClaw. Follow the instructions in the system prompt to assist users effectively.`;

  // Write the system prompt to test_env_snapshot.txt
  const snapshotPath = path.resolve(__dirname, 'test_env_snapshot.txt');
  fs.writeFileSync(snapshotPath, systemPrompt, 'utf8');

  // Optional: log that setup completed
  // console.log('Global setup completed. System prompt written to test_env_snapshot.txt');
}

module.exports = setup;
